'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided-base-reinterpret-complex128' );


// MAIN //

/**
* Tests whether at least one element in a double-precision complex floating-point strided array is truthy using alternative indexing semantics.
*
* ## Notes
*
* -   A complex number is truthy when at least one of its real or imaginary components is truthy.
* -   The function explicitly treats `NaN` values as falsy.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex128Array} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {boolean} boolean indicating whether at least one element is truthy
*
* @example
* var Complex128Array = require( '@stdlib/array-complex128' );
*
* var x = new Complex128Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = zany( x.length, x, 1, 0 );
* // returns true
*/
function zany( N, x, strideX, offsetX ) {
	var view;
	var ix;
	var i;

	if ( N <= 0 ) {
		return false;
	}

	// Reinterpret the complex input array as a real-valued array of interleaved real and imaginary components:
	view = reinterpret( x, 0 );

	// Adjust the stride and offset to account for the interleaved storage:
	ix = offsetX * 2;
	strideX *= 2;

	for ( i = 0; i < N; i++ ) {
		if ( view[ ix ] || view[ ix+1 ] ) {
			return true;
		}
		ix += strideX;
	}
	return false;
}


// EXPORTS //

module.exports = zany;
